import hashlib, json, re
from html.parser import HTMLParser
from pathlib import Path

class TextParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.hidden = 0
        self.parts = []

    def handle_starttag(self, tag, attrs):
        if tag in ('script', 'style'):
            self.hidden += 1
        elif not self.hidden and tag in ('p', 'li', 'tr', 'h1', 'h2', 'h3', 'br'):
            self.parts.append('\n')

    def handle_endtag(self, tag):
        if tag in ('script', 'style'):
            self.hidden = max(0, self.hidden - 1)
        elif not self.hidden and tag in ('p', 'li', 'tr', 'h1', 'h2', 'h3'):
            self.parts.append('\n')

    def handle_data(self, data):
        if not self.hidden:
            self.parts.append(data)

root = Path('products/services/sqlite-lemon-squeezy')
patterns = {
    'activate-your-store': r'verif|activat|approv|questionnaire|business|identity',
    'getting-paid': r'payout|minimum|threshold|hold|currency|conversion',
    'fees': r'\$|%|fee|conversion',
    'supported-countries': r'\bCanada\b',
    'prohibited-products': r'license|licence|redistribut|intellectual|artificial intelligence|AI.generated|digital goods|services',
}
result = {}
for page, pattern in patterns.items():
    source = root / 'raw' / (page + '.html')
    data = source.read_bytes()
    parser = TextParser()
    parser.feed(data.decode('utf-8'))
    lines = [' '.join(line.split()) for line in ''.join(parser.parts).splitlines()]
    excerpts = list(dict.fromkeys(line[:1000] for line in lines if re.search(pattern, line, re.I)))
    result[page] = {'url': 'https://docs.lemonsqueezy.com/help/getting-started/' + page, 'source_sha256': hashlib.sha256(data).hexdigest(), 'matched_lines': len(excerpts), 'excerpts': excerpts[:60]}
output = root / 'seller-terms-excerpts.json'
output.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(json.dumps({page: record['matched_lines'] for page, record in result.items()}))
